    h, w = len(grid), len(grid[0])
    # Single-color, nonzero separator lines partition the grid into panels.
    row_lines = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    col_lines = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]

    def bands(size, lines):
        result = []
        start = 0
        for line in lines:
            if start < line:
                result.append((start, line))
            start = line + 1
        if start < size:
            result.append((start, size))
        return result

    row_bands = bands(h, row_lines)
    col_bands = bands(w, col_lines)
    if not row_bands or not col_bands:
        return [row[:] for row in grid]

    # The leftmost cell-panel in each row gives that row's output color.
    seed_colors = []
    for r0, r1 in row_bands:
        colors = [grid[r][c] for r in range(r0, r1)
                  for c in range(col_bands[0][0], col_bands[0][1])
                  if grid[r][c] != 0]
        seed_colors.append(colors[0] if colors else 0)

    # A separate panel contains the shape to stamp across all panels.
    motif = None
    for r0, r1 in row_bands:
        for c0, c1 in col_bands[1:]:
            points = [(r - r0, c - c0)
                      for r in range(r0, r1) for c in range(c0, c1)
                      if grid[r][c] != 0]
            if points:
                motif = points
                break
        if motif is not None:
            break
    if motif is None:
        return [row[:] for row in grid]

    out = [[0 for _ in range(w)] for _ in range(h)]
    # Preserve the separators exactly.
    for r in row_lines:
        out[r] = grid[r][:]
    for c in col_lines:
        for r in range(h):
            out[r][c] = grid[r][c]

    for i, (r0, r1) in enumerate(row_bands):
        color = seed_colors[i]
        for c0, c1 in col_bands:
            for dr, dc in motif:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = color
    return out
